    temp_q.z = a * nq0.z + b * nq1.z;

    if (adcs_quat_normalize(&temp_q, interpolated_q_bi) != ADCS_OK) {
        *interpolated_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    return ADCS_OK;
}
